{
  "name": "scan_calc_adv_params",
  "confidence": "medium",
  "docstring": "Calculates and returns a packed 16-bit BLE scan/advertising control word (mode, channel/map, interval bits, and flags) by randomly selecting values from the scan context parameters.",
  "subsystem": "ble",
  "var_renames": {
    "a1": "scan_ctx",
    "v2": "rand_value",
    "v3": "adv_mode",
    "v4": "param_max",
    "v5": "rand_bits",
    "v7": "param_min",
    "v8": "channel_min",
    "v10": "adv_channel",
    "v34": "selected_bit",
    "v36": "map_index",
    "v37": "map_mask_byte",
    "v38": "bit_index"
  },
  "struct_hints": [
    {
      "offset": 169,
      "meaning": "advertising/scan mode or type used as the high 11-bit field"
    },
    {
      "offset": 170,
      "meaning": "byte array/channel map base, indexed by map_index"
    },
    {
      "offset": 174,
      "meaning": "16-bit allowed-channel or parameter mask"
    },
    {
      "offset": 176,
      "meaning": "limit for the selected bit/channel index"
    },
    {
      "offset": 177,
      "meaning": "minimum channel/range value"
    },
    {
      "offset": 178,
      "meaning": "maximum/fallback channel value"
    },
    {
      "offset": 179,
      "meaning": "maximum value for the random range/interval field"
    },
    {
      "offset": 180,
      "meaning": "count/limit for map_index selection"
    },
    {
      "offset": 182,
      "meaning": "advertising/scan flag or policy byte encoded around bit 10"
    }
  ]
}
